// SAFE INPUT VALIDATION
const input = $input.item.json.body || $input.item.json;

if (!input.document && !input.document_base64 && !input.image_url && !input.file_url) {
  throw new Error('Missing document: provide document, document_base64, image_url, or file_url');
}

return {
  document: input.document || input.document_base64 || input.image_url || input.file_url,
  document_id: input.document_id || `doc_${Date.now()}`,
  scheme_id: input.scheme_id || 'unknown',
  language: input.language || 'en',
  source: input.source || 'webhook',
  user_data: input.user_data || {},
  timestamp: new Date().toISOString()
};

// SAFE FALLBACK FOR OCR FAILURE
const inputData = $node['Validate Input']?.json || {};

return {
  document_type: 'unknown',
  extracted_fields: inputData.user_data?.extracted_fields || {},
  confidence: 0,
  ocr_text: '',
  needs_manual_review: true,
  error: 'OCR extraction failed',
  document_id: inputData.document_id,
  scheme_id: inputData.scheme_id,
  status: 'ocr_failed',
  user_data: inputData.user_data
};

// SAFE FIELD MAPPING WITH FALLBACKS
const getData = (nodeName) => {
  try {
    return $node[nodeName]?.json || {};
  } catch (e) {
    return {};
  }
};

const ocr = getData('OCR Extraction');
const layout = getData('LayoutLM Analysis');
const input = getData('Validate Input');

// Merge user-provided data with OCR results
const userFields = input?.user_data?.extracted_fields || {};
const ocrFields = {
  full_text: ocr?.text || '',
  ...layout?.entities
};

const fields = { ...userFields, ...ocrFields };

// Calculate confidence
const ocrConfidence = ocr?.confidence || 0;
const layoutConfidence = layout?.confidence || 0;
const confidence = Math.max(ocrConfidence, layoutConfidence, Object.keys(userFields).length > 0 ? 0.75 : 0);

return {
  extracted_fields: fields,
  confidence: confidence,
  needs_manual_review: confidence < 0.7,
  status: 'processed',
  document_id: input?.document_id,
  scheme_id: input?.scheme_id
};

// SAFE RESPONSE BUILDER
const getData = (name) => {
  try {
    return $node[name]?.json || {};
  } catch (e) {
    return {};
  }
};

const successSub = getData('Create Submission');
const manualSub = getData('Flag for Manual Review');
const fieldData = getData('Field Mapping');
const fallbackData = getData('OCR Fallback');

// Determine which path was taken
const submission = Object.keys(successSub).length > 0 ? successSub : manualSub;
const finalFields = Object.keys(fieldData).length > 0 ? fieldData : fallbackData;

// Build response
let status = 'unknown';
let message = '';

if (finalFields.status === 'ocr_failed') {
  status = 'failed';
  message = 'OCR extraction failed - document needs manual processing';
} else if (finalFields.needs_manual_review) {
  status = 'pending_review';
  message = 'Document submitted for CHW review due to low confidence';
} else {
  status = submission.status || 'processed';
  message = 'Document processed successfully';
}

return {
  success: status !== 'failed',
  submission_id: submission.submission_id || submission.id || `sub_${Date.now()}`,
  document_id: finalFields.document_id || 'unknown',
  status: status,
  extracted_fields: finalFields.extracted_fields || {},
  confidence: finalFields.confidence || 0,
  needs_review: finalFields.needs_manual_review || false,
  message: message,
  processed_at: new Date().toISOString()
};

// PARSE ULTRAVOX WEBHOOK DATA SAFELY
const body = $input.item.json.body || $input.item.json;

// Ultravox sends event type and call object
const eventType = body.event || 'unknown';
const call = body.call || {};
const callId = call.callId || call.call_id || 'unknown';

// Extract transcript (varies by event type)
let transcript = '';
if (call.transcript) {
  transcript = typeof call.transcript === 'string' ? call.transcript : call.transcript.text || '';
} else if (call.messages && Array.isArray(call.messages)) {
  transcript = call.messages.map(m => m.text || m.content || '').join(' ');
}

const extractedData = {
  event_type: eventType,
  call_id: callId,
  transcript: transcript,
  call_status: call.status || call.state || 'unknown',
  duration: call.duration || 0,
  metadata: call.metadata || {},
  timestamp: new Date().toISOString(),
  raw_call: call
};

console.log(`[Ultravox] Event: ${eventType}, Call ID: ${callId}, Status: ${extractedData.call_status}`);

return extractedData;

// EXTRACT STRUCTURED DATA FROM TRANSCRIPT
const data = $input.item.json;
const transcript = data.transcript || '';
const callId = data.call_id;

// Helper function to extract field using multiple patterns
function extractField(text, patterns) {
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match && match[1]) return match[1].trim();
  }
  return null;
}

// Extract common fields (English + Tamil patterns)
const extractedFields = {
  name: extractField(transcript, [
    /name is ([A-Za-z\s]+)/i,
    /my name is ([A-Za-z\s]+)/i,
    /பெயர்[:\s]+([^,\.\n]+)/i,
    /என் பெயர் ([^,\.\n]+)/i
  ]),
  age: extractField(transcript, [
    /age is (\d+)/i,
    /(\d+) years old/i,
    /வயது[:\s]+(\d+)/i
  ]),
  ration_card: extractField(transcript, [
    /ration card[:\s]+([A-Z0-9]+)/i,
    /card number[:\s]+([A-Z0-9]+)/i,
    /குடும்ப அட்டை[:\s]+([A-Z0-9]+)/i
  ]),
  income: extractField(transcript, [
    /income[:\s]+(\d+)/i,
    /earn[:\s]+(\d+)/i,
    /salary[:\s]+(\d+)/i,
    /வருமானம்[:\s]+(\d+)/i
  ]),
  children: extractField(transcript, [
    /(\d+) children/i,
    /children[:\s]+(\d+)/i,
    /குழந்தைகள்[:\s]+(\d+)/i
  ])
};

// Remove null values
const cleanedFields = {};
for (const [key, value] of Object.entries(extractedFields)) {
  if (value !== null) cleanedFields[key] = value;
}

// Calculate confidence based on extracted fields
const fieldsFound = Object.keys(cleanedFields).length;
const confidence = Math.min(0.95, 0.5 + (fieldsFound * 0.1));

const documentPayload = {
  file_url: `voice://ultravox/${callId}`,
  file_id: `voice_${callId}_${Date.now()}`,
  language: "tam+eng",
  state_code: "TN",
  doc_type: "voice_application",
  source: "ultravox_voice_call",
  user_data: {
    source: "ultravox_voice_call",
    call_id: callId,
    transcript: transcript,
    extracted_fields: cleanedFields,
    confidence: confidence,
    fields_extracted_count: fieldsFound
  }
};

console.log(`[Voice Processing] Extracted ${fieldsFound} fields with ${confidence} confidence`);

return documentPayload;

// BUILD RESPONSE FOR ULTRAVOX
const getData = (name) => {
  try {
    return $node[name]?.json || {};
  } catch (e) {
    return {};
  }
};

const pipelineResult = getData('Submit to Document Pipeline');
const voiceData = getData('Extract Data from Voice');
const parsedData = getData('Parse Ultravox Data');

const callId = parsedData.call_id;

// Check if pipeline succeeded
const success = pipelineResult.success !== false && !pipelineResult.error;

const response = {
  success: success,
  call_id: callId,
  message: success 
    ? "Your application has been received and is being processed" 
    : "We received your call but need manual review",
  results: {
    manifest_id: pipelineResult.manifest_id || pipelineResult.submission_id,
    extracted_fields: voiceData.user_data?.extracted_fields || {},
    confidence: voiceData.user_data?.confidence || 0,
    status: pipelineResult.status || 'pending',
    needs_review: pipelineResult.needs_review || false
  },
  voice_response: generateVoiceResponse(pipelineResult, voiceData)
};

function generateVoiceResponse(result, voice) {
  const fieldsCount = Object.keys(voice.user_data?.extracted_fields || {}).length;

  if (result.success && !result.needs_review) {
    return `உங்கள் விண்ணப்பம் பதிவு செய்யப்பட்டது. ${fieldsCount} விவரங்கள் பெறப்பட்டன. சமூக சுகாதார ஊழியர் விரைவில் உங்களை தொடர்பு கொள்வார்.`;
  } else if (result.needs_review) {
    return "உங்கள் விண்ணப்பம் பெறப்பட்டது. சமூக சுகாதார ஊழியர் விவரங்களை சரிபார்த்து உங்களை தொடர்பு கொள்வார்.";
  } else {
    return "உங்கள் தகவல் பெறப்பட்டது. மேலும் விவரங்களுக்கு சமூக சுகாதார ஊழியரை தொடர்பு கொள்ளவும்.";
  }
}

return response;

// ACKNOWLEDGE OTHER EVENTS (call.started, call.joined, etc.)
const parsedData = $node['Parse Ultravox Data']?.json || {};
const callId = parsedData.call_id;
const eventType = parsedData.event_type;

return {
  success: true,
  call_id: callId,
  event_type: eventType,
  message: `Event ${eventType} received for call ${callId}`,
  status: "acknowledged"
};

// LANGUAGE DETECTION & QUERY PARSING
const input = $input.item.json.body || $input.item.json;
const query = input.query || input.q || '';

if (!query) {
  throw new Error('Missing query parameter');
}

// Detect language based on Unicode ranges
let lang = 'en-IN';
if (/[\u0900-\u097F]/.test(query)) lang = 'hi-IN';  // Hindi
else if (/[\u0B80-\u0BFF]/.test(query)) lang = 'ta-IN';  // Tamil
else if (/[\u0D00-\u0D7F]/.test(query)) lang = 'ml-IN';  // Malayalam
else if (/[\u0C80-\u0CFF]/.test(query)) lang = 'kn-IN';  // Kannada
else if (/[\u0A80-\u0AFF]/.test(query)) lang = 'gu-IN';  // Gujarati

return {
  query: query,
  detected_language: lang,
  user_data: input.user_data || {},
  session_id: input.session_id || `session_${Date.now()}`,
  timestamp: new Date().toISOString()
};

// PREPARE SEARCH QUERY
const getData = (name) => {
  try {
    return $node[name]?.json || {};
  } catch (e) {
    return {};
  }
};

const originalData = getData('Parse & Detect Language');
const translationData = getData('Translate Query');

// Use translated text if available, otherwise use original
const searchQuery = translationData.translated_text || translationData.text || originalData.query;

return {
  search_query: searchQuery,
  original_query: originalData.query,
  language: originalData.detected_language,
  session_id: originalData.session_id
};

// PROCESS AND DEDUPLICATE RESULTS
const getData = (name) => {
  try {
    return $node[name]?.json || {};
  } catch (e) {
    return {};
  }
};

const ragData = getData('RAG Search');
const webData = getData('Web Scraper');

// Collect all schemes
const allSchemes = [];
const seenIds = new Set();

// Process RAG results
if (ragData.results && Array.isArray(ragData.results)) {
  ragData.results.forEach(r => {
    const id = r.id || r.scheme_id;
    if (!seenIds.has(id)) {
      allSchemes.push({
        id: id,
        title: r.title || r.metadata?.title,
        description: r.description || r.content || r.text,
        score: r.score || r.relevance_score || 0,
        source: 'rag',
        eligibility: r.eligibility || r.metadata?.eligibility
      });
      seenIds.add(id);
    }
  });
}

// Process Web results
if (webData.results && Array.isArray(webData.results)) {
  webData.results.forEach(r => {
    const id = r.id || r.scheme_id || r.title;
    if (!seenIds.has(id)) {
      allSchemes.push({
        id: id,
        title: r.title || r.name,
        description: r.description || r.content,
        score: r.score || r.relevance || 0.5,
        source: 'web',
        eligibility: r.eligibility
      });
      seenIds.add(id);
    }
  });
}

// Sort by score and take top results
allSchemes.sort((a, b) => b.score - a.score);
const topSchemes = allSchemes.slice(0, 5);

return {
  schemes: topSchemes,
  total_found: allSchemes.length,
  search_query: getData('Prepare Search Query').search_query
};

