// BUILD FINAL RESPONSE
const getData = (name) => {
  try {
    return $node[name]?.json || {};
  } catch (e) {
    return {};
  }
};

const processedData = getData('Process & Deduplicate');
const translationData = getData('Translate Titles');
const originalData = getData('Parse & Detect Language');

const schemes = processedData.schemes || [];
const translations = translationData.results || [];

// Attach translations to schemes
schemes.forEach((scheme, i) => {
  if (translations[i]) {
    scheme.title_translated = translations[i].translated || translations[i].text;
  }
});

// Build response
const response = {
  success: true,
  query: originalData.query,
  detected_language: originalData.detected_language,
  session_id: originalData.session_id,
  schemes_found: schemes,
  total_schemes: schemes.length,
  message: schemes.length > 0 
    ? `Found ${schemes.length} relevant scheme(s)` 
    : 'No schemes found matching your query',
  timestamp: new Date().toISOString()
};

return response;
